// Normalise the request into one item per persona, which is what the loop
// iterates over.
//
// Personas arrive in whatever shape the caller had to hand - full objects, or
// just names. Anything usable is accepted and filled in; what is not supplied
// falls back to a default library, because a QA who has not written personas
// yet is exactly the person this engine is for.

const MAX_PERSONAS = 6; // 8,000 tokens/minute is ~3 personas/minute; beyond six
                        // the run takes long enough that a human should be
                        // choosing which ones matter.

const hook = $('Persona Webhook').first().json;
const body = (hook && hook.body) || hook || {};

const feature = String(body.feature || body.feature_description || '').trim();
const featureName = String(body.feature_name || 'Untitled feature').trim();

// Deliberately not a list of demographics. Each one carries traits that change
// what a person DOES, because those are the only traits a test flow can act on.
const DEFAULT_LIBRARY = [
  {
    name: 'Power User',
    summary: 'Uses the product daily and knows it better than most of the team.',
    traits: ['expects keyboard shortcuts', 'works at speed and skips confirmations',
      'has bulk and edge-case data', 'will find undocumented paths', 'low tolerance for extra clicks'],
  },
  {
    name: 'First-Time User',
    summary: 'Has never seen this product and arrived with a job to do.',
    traits: ['does not know the vocabulary', 'reads labels literally',
      'unsure which action is safe', 'will abandon if confused', 'expects to be able to undo'],
  },
  {
    name: 'Senior Citizen',
    summary: 'Comfortable with a phone and a browser, not with jargon or speed.',
    traits: ['low vision, uses larger text', 'less precise tapping and clicking',
      'needs longer than a default session timeout', 'cautious about anything involving money',
      'wants confirmation that something worked'],
  },
  {
    name: 'Screen-Reader User',
    summary: 'Navigates entirely by keyboard with a screen reader.',
    traits: ['never uses a mouse', 'relies on labels, headings and focus order',
      'cannot see colour-only status', 'needs errors announced, not just shown in red',
      'trapped focus makes the feature unusable'],
  },
  {
    name: 'Mobile-Only on a slow connection',
    summary: 'Has no laptop and is on intermittent 3G.',
    traits: ['small screen, one thumb', 'requests time out and are retried',
      'may lose connection mid-task', 'data costs matter', 'interruptions from calls and notifications'],
  },
];

function normalise(p, i) {
  if (typeof p === 'string') {
    return { name: p.trim() || 'Persona ' + (i + 1), summary: '', traits: [], supplied: true };
  }
  const o = p || {};
  const traits = Array.isArray(o.traits) ? o.traits
    : (typeof o.traits === 'string' ? o.traits.split(/[;\n]/) : []);
  return {
    name: String(o.name || o.persona || 'Persona ' + (i + 1)).trim(),
    summary: String(o.summary || o.description || '').trim(),
    traits: traits.map((t) => String(t).trim()).filter(Boolean),
    context: String(o.context || '').trim(),
    goals: String(o.goals || o.goal || '').trim(),
    supplied: true,
  };
}

const supplied = Array.isArray(body.personas) ? body.personas.filter(Boolean) : [];
let personas = supplied.map(normalise).filter((p) => p.name);
let usedLibrary = false;

if (!personas.length) {
  usedLibrary = true;
  personas = DEFAULT_LIBRARY.map((p) => Object.assign({}, p, { supplied: false }));
}

const dropped = Math.max(0, personas.length - MAX_PERSONAS);
personas = personas.slice(0, MAX_PERSONAS);

// A run id ties every row of a run together in the sheet, so two runs against
// the same feature do not read as one.
const runId = 'run-' + Date.now().toString(36);
const generatedAt = new Date().toISOString();

if (!feature) {
  throw new Error('No feature description supplied. Send { "feature": "what the feature does" }.');
}

return personas.map((p) => ({
  json: {
    run_id: runId,
    generated_at: generatedAt,
    feature_name: featureName,
    feature,
    persona_name: p.name,
    persona_summary: p.summary,
    persona_traits: p.traits,
    persona_context: p.context || '',
    persona_goals: p.goals || '',
    persona_supplied: p.supplied,
    used_default_library: usedLibrary,
    personas_total: personas.length,
    personas_dropped: dropped,
  },
}));

parameters.text:
=FEATURE: {{ $json.feature_name }}

{{ $json.feature }}

--- THE PERSONA YOU ARE WRITING FOR ---
Name: {{ $json.persona_name }}
Summary: {{ $json.persona_summary }}
Goals: {{ $json.persona_goals }}
Traits:
{{ ($json.persona_traits || []).map(t => "  - " + t).join("\n") }}

Write the test flow this person - and only this person - would produce against this feature.
Every step must name the trait that causes it. Anything this person needs that the feature
description above does not mention is a gap, not a step.

