      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Specific moments where this persona struggles."
    },
    "accessibility_notes": {
      "type": "string",
      "description": "Only when the persona implies them; \"None\" is a valid answer."
    },
    "gaps": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Questions for the product owner about what the description does not cover."
    },
    "priority": {
      "type": "string",
      "enum": [
        "High",
        "Medium",
        "Low"
      ]
    }
  }
}

parameters.jsCode:
// Per-persona guard rails, applied before the flow is allowed to count.
//
// The schema already guarantees the shape. What it cannot guarantee is that the
// content is about THIS persona, which is the only thing that makes the output
// worth having. Two checks do that here, and a third across personas happens
// after the loop.

const ctx = $('Loop Over Personas').first().json;
const incoming = $input.first().json;
const model = (incoming && incoming.output) || incoming || {};

const notes = [];
const str = (v, fallback) => {
  if (v === undefined || v === null) return fallback;
  const s = String(v).trim();
  return s === '' ? fallback : s;
};
const arr = (v) => (Array.isArray(v) ? v : []);
const norm = (s) => String(s).toLowerCase().replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();

const traits = arr(ctx.persona_traits).map(String);
const traitText = norm(traits.join(' ') + ' ' + (ctx.persona_summary || ''));
const featureText = norm(ctx.feature || '');

// --- guard rail 2: no step without a trait ---------------------------------
// A step whose driven_by is missing, or merely restates the action, belongs to
// no persona. It is a generic step wearing a costume.
let dropped = 0;
const steps = arr(model.steps)
  .map((s, i) => ({
    step_no: Number(s && s.step_no) || i + 1,
    action: str(s && s.action, ''),
    expected: str(s && s.expected, 'Not Provided'),
    driven_by: str(s && s.driven_by, ''),
    risk: str(s && s.risk, 'Not Provided'),
  }))
  .filter((s) => {
    if (!s.action) { dropped++; return false; }
    if (!s.driven_by) { dropped++; return false; }
    // A driven_by that just echoes the action explains nothing. Compared on
    // word stems rather than exact text, because "entering the card number"
    // against "Enter the card number" is the same non-answer and a literal
    // comparison waves it through.
    const a = norm(s.action);
    const dWords = norm(s.driven_by).split(' ').filter((w) => w.length > 3);
    if (dWords.length) {
      const echoed = dWords.filter((w) => a.includes(w.slice(0, 5))).length;
      if (echoed / dWords.length >= 0.8) { dropped++; return false; }
    }
    return true;
  })
  .map((s, i) => Object.assign({}, s, { step_no: i + 1 }));

if (dropped) notes.push(dropped + ' step(s) dropped for naming no persona trait');

// How much of this flow is anchored in a trait the persona actually has?
// Loose matching on purpose - the model paraphrases, and it should be allowed to.
let anchored = 0;
steps.forEach((s) => {
  const words = norm(s.driven_by).split(' ').filter((w) => w.length > 3);
  if (words.some((w) => traitText.includes(w))) anchored++;
});
const anchoredPct = steps.length ? Math.round((anchored / steps.length) * 100) : 0;
if (steps.length && anchoredPct < 50) {
  notes.push('only ' + anchoredPct + '% of steps cite a trait this persona was given');
}

// --- guard rail 3: no inventing the product --------------------------------
// Quoted UI names are the checkable case: if the model puts a control in quotes,
// the feature description should mention it.
const invented = [];
steps.forEach((s) => {
  const text = s.action + ' ' + s.expected;
  for (const m of text.matchAll(/["'“‘]([A-Za-z][A-Za-z0-9 ]{1,28})["'”’]/g)) {
    const name = norm(m[1]);
    if (name.length < 3) continue;
    if (!featureText.includes(name) && !invented.includes(m[1])) invented.push(m[1]);
  }
});
if (invented.length) {
  notes.push('names not found in the feature description: ' + invented.slice(0, 6).join(', '));
}

const PRIORITIES = ['High', 'Medium', 'Low'];
const priority = PRIORITIES.find((p) => p.toLowerCase() === str(model.priority, '').toLowerCase()) || 'Medium';

const flow = {
  run_id: ctx.run_id,
  generated_at: ctx.generated_at,
  feature_name: ctx.feature_name,
  feature: ctx.feature,
  persona_name: ctx.persona_name,
  persona_supplied: ctx.persona_supplied,
  used_default_library: ctx.used_default_library,
  personas_total: ctx.personas_total,

  persona_summary: str(model.persona_summary, ctx.persona_summary || 'Not Provided'),
  primary_goal: str(model.primary_goal, 'Not Provided'),
  steps,
  step_count: steps.length,
  steps_dropped: dropped,
  trait_anchored_pct: anchoredPct,
  friction_points: arr(model.friction_points).map((f) => String(f).trim()).filter(Boolean).slice(0, 6),
  accessibility_notes: str(model.accessibility_notes, 'None'),
  gaps: arr(model.gaps).map((g) => String(g).trim()).filter(Boolean).slice(0, 6),
  priority,
  invented_names: invented.slice(0, 6),
  validation_notes: notes.length ? notes : ['No corrections were needed'],
};

return [{ json: flow }];

// The check that only exists once every persona has been generated.
//
// Guard rail 1: two personas that produce the same flow mean the personas were
// ignored. Nothing about such a run is malformed - the schema passes, each flow
// reads fine on its own - and it is worthless. The only way to catch it is to
// compare the flows against each other, which cannot happen inside the loop
// because each iteration only sees itself.
//
// This node also flattens the flows into one row per step, which is the shape a
// QA can actually work from: filter by persona, assign, tick off.

const CONVERGENCE_LIMIT = 0.6; // above this two flows are substantially the same

const flows = $input.all().map((i) => i.json).filter((f) => f && f.persona_name);

const STOP = new Set(['the', 'a', 'an', 'and', 'or', 'to', 'of', 'in', 'on', 'for', 'with',
  'is', 'are', 'be', 'that', 'this', 'it', 'as', 'at', 'by', 'from', 'then', 'their', 'they',
  'user', 'users', 'page', 'screen', 'app', 'click', 'clicks', 'tap', 'taps', 'open', 'opens']);

// Compare on the meaningful words of the actions. Common verbs like "click" are
// stripped, because every flow clicks - what differs is what they click and why.
function fingerprint(flow) {
  const words = (flow.steps || [])
    .map((s) => String(s.action || ''))
    .join(' ')
    .toLowerCase()
    .replace(/[^a-z0-9 ]/g, ' ')
    .split(/\s+/)
    .filter((w) => w.length > 3 && !STOP.has(w));
  return new Set(words);
}

function jaccard(a, b) {
  if (!a.size || !b.size) return 0;
  let shared = 0;
  a.forEach((w) => { if (b.has(w)) shared++; });
  return shared / (a.size + b.size - shared);
}

const prints = flows.map(fingerprint);
const pairs = [];
for (let i = 0; i < flows.length; i++) {
  for (let j = i + 1; j < flows.length; j++) {
    pairs.push({
      a: flows[i].persona_name,
      b: flows[j].persona_name,
      overlap: Math.round(jaccard(prints[i], prints[j]) * 100),
    });
  }
}
pairs.sort((x, y) => y.overlap - x.overlap);

const converged = pairs.filter((p) => p.overlap >= CONVERGENCE_LIMIT * 100);
const worst = pairs[0] || null;
const flagged = converged.length > 0;

const runNotes = [];
if (flagged) {
  runNotes.push('flows converged: ' + converged.map((p) => p.a + ' / ' + p.b + ' ' + p.overlap + '%').join('; ') +
    ' - the personas may have been ignored');
}
const thin = flows.filter((f) => f.trait_anchored_pct < 50).map((f) => f.persona_name);
if (thin.length) runNotes.push('weakly anchored to persona traits: ' + thin.join(', '));
const withInvented = flows.filter((f) => (f.invented_names || []).length).map((f) => f.persona_name);
if (withInvented.length) runNotes.push('named things the feature description does not mention: ' + withInvented.join(', '));

const first = flows[0] || {};
const totalSteps = flows.reduce((n, f) => n + (f.steps || []).length, 0);
const allGaps = [];
flows.forEach((f) => (f.gaps || []).forEach((g) => { if (!allGaps.includes(g)) allGaps.push(g); }));

// --- the Telegram summary ---------------------------------------------------
const telegram_text = [
  'Persona test flows - ' + (first.feature_name || 'feature'),
  '',
  flows.length + ' personas, ' + totalSteps + ' test steps generated.',
  first.used_default_library ? 'Personas: default library (none were supplied).' : 'Personas: supplied with the request.',
  '',
  'Coverage:',
  flows.map((f) => '  ' + f.persona_name + ' - ' + (f.steps || []).length + ' steps, priority ' + f.priority).join('\n'),
  '',
  worst ? 'Most similar pair: ' + worst.a + ' / ' + worst.b + ' at ' + worst.overlap + '% overlap' +
    (flagged ? '  <-- too similar, check the personas were used' : '  (flows are distinct)') : '',
  '',
  allGaps.length ? 'Gaps raised for the product owner:\n' + allGaps.slice(0, 6).map((g, i) => (i + 1) + '. ' + g).join('\n') : 'No gaps raised.',
  '',
  runNotes.length ? 'Notes: ' + runNotes.join(' | ') : 'No validation problems.',
].join('\n');

// --- one row per step -------------------------------------------------------
const rows = [];
flows.forEach((f) => {
  (f.steps || []).forEach((s) => {
    rows.push({
      run_id: f.run_id,
      generated_at: f.generated_at,
      feature: f.feature_name,
      persona: f.persona_name,
      priority: f.priority,
      step_no: s.step_no,
      action: s.action,
      expected: s.expected,
      driven_by: s.driven_by,
      risk: s.risk,
      primary_goal: f.primary_goal,
      accessibility_notes: f.accessibility_notes,
      persona_source: f.used_default_library ? 'default library' : 'supplied',
    });
  });
});

if (!rows.length) {
  // Never write an empty run silently - an empty sheet reads as "no issues".
  rows.push({
    run_id: first.run_id || 'unknown',
    generated_at: first.generated_at || new Date().toISOString(),
    feature: first.feature_name || 'Unknown',
    persona: 'NONE',
    priority: 'High',
    step_no: 1,
    action: 'No test steps were generated',
    expected: 'Investigate: every generated step failed validation, or no personas ran',
    driven_by: 'n/a',
    risk: 'A run that produces nothing must not be mistaken for a feature with no risks',
    primary_goal: 'n/a',
    accessibility_notes: 'n/a',
    persona_source: 'n/a',
  });
  runNotes.push('no steps survived validation');
}

// Run-level fields ride on the first row; the Sheets node maps columns
// explicitly, so the extra keys are ignored there.
rows[0].telegram_text = telegram_text;
rows[0].personas_analyzed = flows.length;
rows[0].total_steps = totalSteps;
rows[0].max_overlap_pct = worst ? worst.overlap : 0;
rows[0].flows_converged = flagged;
rows[0].pair_overlaps = pairs;
rows[0].gaps = allGaps;
rows[0].run_notes = runNotes.length ? runNotes : ['No validation problems'];

return rows.map((json) => ({ json }));
